public Task CacheAttemptAsync(string attemptId, byte[] payload, IMemoryCache cache)
{
    cache.GetOrCreate(attemptId, _ => payload); // captures payload

    return cache.GetOrCreateAsync(
        attemptId,
        static entry =>
        {
            entry.AbsoluteExpirationRelativeToNow = TimeSpan.FromMinutes(5);
            return Task.FromResult(ReadOnlyMemory<byte>.Empty);
        });
}

IQueryable<Attempt> query = db.Attempts;

// Expression tree — EF translates to SQL
Expression<Func<Attempt, bool>> activeFilter = a => a.Status == AttemptStatus.Active;
var active = query.Where(activeFilter);

// Statement lambda — NOT an expression tree; use only on IEnumerable
Func<Attempt, bool> inMemory = a =>
{
    var cutoff = DateTime.UtcNow.AddDays(-7);
    return a.SubmittedAt > cutoff;
};
var recent = db.Attempts.AsEnumerable().Where(inMemory);
